/* Thermosys - VANNES : (1) calcul du Kvs sans valeur par defaut silencieuse (entrees invalides refusees) ;
   (2) calculateur de perte de charge / debit reecrit : eau uniquement, proprietes de l'eau a la temperature du regime, Swamee-Jain, pas de coefficient arbitraire 1,4,
       Kv requis, Kvs normalise (R5), autorite, vitesse hors plage signalee, debit massique en kg/s et g/s (l'ancien « kg/min » etait faux) ;
   (3) « paliers » : les tables de constructeurs (IMI, TA, Danfoss, Belimo) etaient inventees : retirees ; table de lecture du Kvs honnete ;
   (4) catalogue : Belimo LM/NM/AM/GM24A-SR sont des servomoteurs de clapets d'air (pas de vannes d'eau) ; avertissement « fiche indicative » sur chaque fiche ; unites « Nm Nm » corrigees ;
   (5) test tests\vannes_regression.js (133 verifications, 35 mutations).
   Usage (depuis le dossier files) :  node patch_vannes_v1.js */
'use strict';
const fs = require('fs'), path = require('path');
const file = process.argv[2] || path.join('dist', 'index.html');
if (!fs.existsSync(file)) { console.error('Fichier introuvable : ' + file); process.exit(2); }
const raw = fs.readFileSync(file, 'utf8'), crlf = raw.indexOf('\r\n') >= 0;
let s = crlf ? raw.replace(/\r\n/g, '\n') : raw;
const MOD = Buffer.from("", 'base64').toString('utf8');
const TEST = Buffer.from("", 'base64').toString('utf8');
function writeTest() {
  fs.mkdirSync('tests', { recursive: true }); fs.writeFileSync(path.join('tests', 'vannes_regression.js'), TEST, 'utf8');
  const rd = path.join('tests', 'README_TESTS.txt'); let r = fs.existsSync(rd) ? fs.readFileSync(rd, 'utf8') : '';
  if (r.indexOf('vannes_regression.js') < 0) fs.writeFileSync(rd, r + (r && !/\n$/.test(r) ? '\n' : '') + '\nvannes_regression.js : VANNES (Kvs, calculateur dP / debit, lecture du Kvs, avertissements du catalogue) : 133 verifications dont 35 mutations. Commande : node tests\\vannes_regression.js\n', 'utf8');
}
if (s.indexOf('THERMOSYS_VANNES_V1') >= 0) { writeTest(); console.log('Deja applique : test reecrit.'); process.exit(0); }
const open = '<script id="vannes37-module">', a = s.indexOf(open);
if (a < 0 || s.indexOf(open, a + 1) >= 0) { console.error('ECHEC ancre vannes37-module : introuvable ou en double. Fichier non modifie.'); process.exit(3); }
const e = s.indexOf('</script>', a);
if (e < 0) { console.error('ECHEC : fin du module vannes37 introuvable.'); process.exit(3); }
const ins = e + '</script>'.length;
s = s.slice(0, ins) + '\n<script id="vannes38-module">\n' + MOD + '</script>' + s.slice(ins);
fs.writeFileSync(file, crlf ? s.replace(/\n/g, '\r\n') : s, 'utf8');
writeTest();
console.log('OK : module vannes38 insere.');
